INSERT INTO exercises (id, name, category, equipment, target, muscle_group, secondary_muscles, instructions_es, image_url, gif_url) VALUES
('1389', 'posterior tibialis stretch', 'lower legs', 'rope', 'calves', 'hamstrings', '{"hamstrings","quadriceps"}', 'Siéntate en el suelo con las piernas extendidas frente a ti. Enrolla la cuerda alrededor de la planta del pie y sujeta los extremos de la cuerda con las manos. Tira suavemente de la cuerda hacia ti, flexionando el pie y estirando los músculos de la pantorrilla. Mantén el estiramiento durante 20-30 segundos. Suelta la tensión de la cuerda y relaja el pie. Repite el estiramiento en la otra pierna.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1389-DEEqoI2.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1389-DEEqoI2.gif'),
('3119', 'potty squat', 'waist', 'body weight', 'abs', 'quadriceps', '{"quadriceps","glutes"}', 'Ponte de pie con los pies separados a la altura de los hombros, los dedos de los pies ligeramente hacia afuera. Baja el cuerpo flexionando las rodillas y empujando las caderas hacia atrás como si te sentaras en una silla. Mantén el pecho hacia arriba y la espalda recta durante todo el movimiento. Baja hasta que los muslos queden paralelos al suelo o hasta donde puedas llegar cómodamente. Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/3119-75Bgtjy.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3119-75Bgtjy.gif'),
('3132', 'potty squat with support', 'upper legs', 'body weight', 'glutes', 'quadriceps', '{"quadriceps","hamstrings","calves"}', 'Ponte de pie con los pies separados a la altura de los hombros, los dedos de los pies ligeramente hacia afuera. Sujétate de un apoyo estable, como una silla o una pared, para mantener el equilibrio. Baja el cuerpo hacia una posición de sentadilla flexionando las rodillas y empujando las caderas hacia atrás. Mantén el pecho hacia arriba y la espalda recta durante todo el movimiento. Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/3132-b63ZzGe.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3132-b63ZzGe.gif'),
('0648', 'power clean', 'upper legs', 'barbell', 'hamstrings', 'glutes', '{"glutes","quadriceps","calves"}', 'Comienza con la barra en el suelo frente a ti, con los pies separados a la altura de los hombros. Agáchate y agarra la barra con un agarre prono, un poco más separado que la anchura de los hombros. Mantén la espalda recta y el pecho hacia arriba al levantar la barra del suelo, extendiendo las caderas y las rodillas. Cuando la barra llegue a la mitad del muslo, tira de ella explosivamente hacia arriba, encogiendo los hombros y llevando los codos hacia arriba y hacia los lados. Cuando la barra alcance su punto más alto, baja rápidamente debajo de ella, rotando los codos y atrapando la barra sobre los hombros en una posición de sentadilla frontal. Ponte de pie con la barra, extendiendo completamente las caderas y las rodillas. Baja la barra de nuevo a la posición inicial, manteniendo el control del peso durante todo el movimiento. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0648-SiWCcTN.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0648-SiWCcTN.gif'),
('3665', 'power point plank', 'waist', 'body weight', 'abs', 'shoulders', '{"shoulders","triceps","glutes"}', 'Comienza en posición de plancha alta con las manos directamente debajo de los hombros y el cuerpo en línea recta de la cabeza a los pies. Activa el core y aprieta los glúteos para mantener una posición estable. Baja el cuerpo hasta los antebrazos, un brazo a la vez, manteniendo una línea recta de la cabeza a los pies. Mantén esta posición durante el tiempo deseado, con el core y los glúteos activados. Para volver a la posición inicial, empuja con los antebrazos y eleva el cuerpo de nuevo a una posición de plancha alta. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/3665-hCjGsRQ.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3665-hCjGsRQ.gif'),
('3203', 'prisoner half sit-up (male)', 'waist', 'body weight', 'abs', 'hip flexors', '{"hip flexors"}', 'Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo. Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera. Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que tu torso forme un ángulo de 45 grados. Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/3203-mgejmGP.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3203-mgejmGP.gif'),
('1707', 'prone twist on stability ball', 'waist', 'stability ball', 'abs', 'obliques', '{"obliques","lower back"}', 'Comienza tumbándote boca abajo sobre un balón de estabilidad con los pies separados a la altura de los hombros y los dedos de los pies tocando el suelo. Coloca las manos detrás de la cabeza o crúzalas sobre el pecho. Activa los músculos del core y eleva lentamente la parte superior del cuerpo del balón, manteniendo la espalda recta. Rota el torso hacia un lado, llevando el hombro hacia la cadera. Mantén las caderas y las piernas estables durante todo el movimiento. Haz una pausa breve y luego vuelve a la posición inicial. Repite la rotación hacia el otro lado. Continúa alternando lados durante el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1707-1IG6gVF.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1707-1IG6gVF.gif'),
('0651', 'pull up (neutral grip)', 'back', 'body weight', 'lats', 'biceps', '{"biceps","forearms"}', 'Cuélgate de una barra de dominadas con un agarre neutro (las palmas enfrentadas) y los brazos completamente extendidos. Activa el core y junta los omóplatos. Tira de tu cuerpo hacia la barra flexionando los codos y llevándolos hacia las caderas. Continúa subiendo hasta que la barbilla quede por encima de la barra. Haz una pausa por un momento en la parte alta y luego baja lentamente tu cuerpo, con control, hasta la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0651-0V2YQjW.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0651-0V2YQjW.gif'),
('0650', 'pull-in (on stability ball)', 'waist', 'stability ball', 'abs', 'hip flexors', '{"hip flexors"}', 'Comienza sentándote en el balón de estabilidad con los pies planos en el suelo y las rodillas flexionadas a un ángulo de 90 grados. Coloca las manos a los lados del balón de estabilidad para mayor apoyo. Activa el abdomen y rueda lentamente las caderas hacia adelante, llevando las rodillas hacia el pecho. Haz una pausa por un momento en la parte alta del movimiento y luego extiende lentamente las piernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0650-UQr48Oi.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0650-UQr48Oi.gif'),
('0652', 'pull-up', 'back', 'body weight', 'lats', 'biceps', '{"biceps","forearms"}', 'Cuélgate de una barra de dominadas con las palmas hacia afuera y los brazos completamente extendidos. Activa el core y junta los omóplatos. Tira de tu cuerpo hacia la barra flexionando los codos y llevando el pecho hacia la barra. Haz una pausa en la parte alta del movimiento y luego baja lentamente el cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0652-lBDjFxJ.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0652-lBDjFxJ.gif'),
('1689', 'push and pull bodyweight', 'chest', 'body weight', 'pectorals', 'triceps', '{"triceps","deltoids"}', 'Comienza en posición de flexión con las manos un poco más separadas que la anchura de los hombros y el cuerpo en línea recta. Baja el pecho hacia el suelo flexionando los codos, manteniendo el cuerpo recto. Empuja con las palmas para extender los brazos y regresar a la posición inicial. Desde la posición de flexión, tira del pecho hacia el suelo flexionando los codos, manteniendo el cuerpo recto. Empuja con las palmas para extender los brazos y regresar a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1689-wXvUZC8.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1689-wXvUZC8.gif'),
('3638', 'push to run', 'cardio', 'body weight', 'cardiovascular system', 'quadriceps', '{"quadriceps","hamstrings","calves"}', 'Comienza en posición de flexión con las manos separadas a la altura de los hombros y el cuerpo en línea recta. Baja el pecho hacia el suelo flexionando los codos, manteniendo el cuerpo recto. Empuja con las manos para extender los brazos y volver a la posición inicial. Lleva rápidamente una rodilla hacia el pecho, luego cambia rápidamente y lleva la otra rodilla hacia el pecho. Continúa alternando las rodillas tan rápido como puedas manteniendo una buena forma. Continúa durante el tiempo o el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/3638-PrQbjvB.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3638-PrQbjvB.gif'),
('1307', 'push up on bosu ball', 'chest', 'bosu ball', 'pectorals', 'triceps', '{"triceps","shoulders","core"}', 'Coloca el bosu en el suelo con el lado plano hacia arriba. Colócate en posición de flexión con las manos en los bordes exteriores del bosu. Activa el core y baja el cuerpo hacia el bosu flexionando los codos. Empuja tu cuerpo de vuelta a la posición inicial extendiendo los brazos. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1307-wVompEp.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1307-wVompEp.gif'),
('0662', 'push-up', 'chest', 'body weight', 'pectorals', 'triceps', '{"triceps","deltoids","core"}', 'Comienza en una posición de plancha alta con las manos un poco más separadas que la anchura de los hombros y los pies juntos. Activa el core y baja el cuerpo hacia el suelo flexionando los codos, manteniendo el cuerpo en línea recta. Haz una pausa cuando el pecho esté justo por encima del suelo y luego empújate de vuelta a la posición inicial estirando los brazos. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0662-I4hDWkc.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0662-I4hDWkc.gif'),
('0653', 'push-up (bosu ball)', 'chest', 'bosu ball', 'pectorals', 'triceps', '{"triceps","shoulders","core"}', 'Coloca el bosu en el suelo con el lado plano hacia arriba. Colócate en posición de flexión con las manos en los bordes exteriores del bosu. Activa el core y baja el cuerpo hacia el bosu flexionando los codos. Empuja tu cuerpo de vuelta a la posición inicial extendiendo los brazos. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0653-2kr2lWy.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0653-2kr2lWy.gif'),
('0655', 'push-up (on stability ball)', 'chest', 'stability ball', 'pectorals', 'triceps', '{"triceps","shoulders","core"}', 'Coloca el balón de estabilidad en el suelo y ponte boca abajo con las manos sobre el balón, separadas a la altura de los hombros. Extiende las piernas rectas detrás de ti, equilibrándote sobre los dedos de los pies. Activa el core y baja el pecho hacia el balón flexionando los codos, manteniendo el cuerpo en línea recta. Haz una pausa breve en la parte baja, luego empújate de nuevo hacia arriba a la posición inicial estirando los brazos. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0655-Y4BRNQF.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0655-Y4BRNQF.gif'),
('0656', 'push-up (on stability ball)', 'chest', 'stability ball', 'pectorals', 'triceps', '{"triceps","shoulders","core"}', 'Coloca el balón de estabilidad en el suelo y ponte boca abajo con las manos sobre el balón, separadas a la altura de los hombros. Extiende las piernas rectas detrás de ti, equilibrándote sobre los dedos de los pies. Activa el core y baja el pecho hacia el balón flexionando los codos, manteniendo el cuerpo en línea recta. Haz una pausa breve en la parte baja, luego empújate de nuevo hacia arriba a la posición inicial estirando los brazos. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0656-tgryw5Y.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0656-tgryw5Y.gif'),
('0659', 'push-up (wall)', 'chest', 'body weight', 'pectorals', 'triceps', '{"triceps","deltoids"}', 'Ponte de pie frente a una pared, a una distancia aproximada de un brazo. Coloca las manos en la pared a la altura de los hombros, un poco más separadas que la anchura de los hombros. Da un paso atrás, manteniendo el cuerpo recto y los pies separados a la altura de las caderas. Flexiona los codos y baja el pecho hacia la pared, manteniendo el cuerpo en línea recta. Empuja de vuelta a la posición inicial, estirando los brazos. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0659-LEH9jxP.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0659-LEH9jxP.gif'),
('0658', 'push-up (wall) v. 2', 'chest', 'body weight', 'pectorals', 'triceps', '{"triceps","shoulders"}', 'Ponte de pie frente a una pared, a una distancia aproximada de un brazo. Coloca las manos en la pared a la altura de los hombros, un poco más separadas que la anchura de los hombros. Retrocede con los pies, manteniéndolos separados a la altura de las caderas. Activa el core y mantén el cuerpo en línea recta desde la cabeza hasta los talones. Flexiona los codos y baja el pecho hacia la pared, manteniendo el cuerpo recto. Haz una pausa por un momento y luego empújate de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0658-NCmbLCw.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0658-NCmbLCw.gif'),
('0660', 'push-up close-grip off dumbbell', 'upper arms', 'dumbbell', 'triceps', 'chest', '{"chest","shoulders"}', 'Comienza en posición de flexión con las manos juntas, directamente debajo de los hombros. Sostén una mancuerna en cada mano, apoyándolas en el suelo. Baja el cuerpo hacia el suelo flexionando los codos, manteniéndolos cerca de los costados. Empuja con las palmas para extender los brazos y regresar a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0660-KZXAtKQ.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0660-KZXAtKQ.gif'),
('0661', 'push-up inside leg kick', 'upper legs', 'body weight', 'glutes', 'quadriceps', '{"quadriceps","hamstrings","calves","core"}', 'Comienza en posición de flexión con las manos un poco más separadas que la anchura de los hombros y los pies juntos. Baja el cuerpo hacia el suelo flexionando los codos, manteniendo la espalda recta y el core activado. Al empujar de vuelta hacia arriba, levanta una pierna del suelo y lánzala hacia el lado, manteniéndola recta. Baja la pierna de nuevo y repite la flexión, luego cambia a la otra pierna. Continúa alternando las patadas de pierna en cada repetición de la flexión.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0661-0br45wL.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0661-0br45wL.gif'),
('0663', 'push-up medicine ball', 'chest', 'medicine ball', 'pectorals', 'triceps', '{"triceps","shoulders","core"}', 'Comienza en una posición de plancha alta con las manos sobre el balón medicinal, separadas a la altura de los hombros. Activa el core y baja el cuerpo hacia el suelo flexionando los codos, manteniendo la espalda recta. Empuja con las palmas para extender los brazos y regresar a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0663-W8KAlkI.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0663-W8KAlkI.gif'),
('1467', 'push-up on lower arms', 'upper arms', 'body weight', 'triceps', 'chest', '{"chest","shoulders"}', 'Comienza en posición de plancha con los antebrazos en el suelo y los codos directamente debajo de los hombros. Activa el core y mantén el cuerpo en línea recta de la cabeza a los pies. Baja el pecho hacia el suelo flexionando los codos, manteniéndolos cerca del cuerpo. Haz una pausa por un momento en la parte inferior, luego empuja tu cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1467-4Jt8QsQ.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1467-4Jt8QsQ.gif'),
('3145', 'push-up plus', 'chest', 'body weight', 'pectorals', 'triceps', '{"triceps","shoulders"}', 'Comienza en una posición de plancha alta con las manos un poco más separadas que la anchura de los hombros y el cuerpo en línea recta desde la cabeza hasta los talones. Baja el cuerpo hacia el suelo flexionando los codos, manteniéndolos cerca de los costados. Cuando el pecho esté justo por encima del suelo, empuja con las manos para extender los brazos y levantar la parte superior del cuerpo. En la parte alta del movimiento, separa las escápulas empujando la parte superior de la espalda hacia el techo. Haz una pausa por un momento y luego invierte el movimiento juntando las escápulas y bajando el cuerpo de nuevo a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/3145-pvBMLHA.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3145-pvBMLHA.gif'),
('0664', 'push-up to side plank', 'waist', 'body weight', 'abs', 'shoulders', '{"shoulders","chest","triceps"}', 'Comienza en posición de flexión con las manos separadas a la altura de los hombros y el cuerpo en línea recta. Baja el cuerpo hacia el suelo flexionando los codos, manteniendo el core activado. Empuja hacia arriba para volver a la posición inicial. Desplaza el peso hacia la mano izquierda y rota el cuerpo hacia la derecha, elevando el brazo derecho hacia el techo. Mantén la posición de plancha lateral durante unos segundos y luego vuelve a la posición inicial. Repite la flexión y la plancha lateral en el lado opuesto. Continúa alternando lados durante el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0664-KhHJ338.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0664-KhHJ338.gif'),
('3533', 'quads', 'upper legs', 'body weight', 'quads', 'hamstrings', '{"hamstrings","glutes"}', 'Ponte de pie con los pies separados a la altura de los hombros. Baja el cuerpo flexionando las rodillas y empujando las caderas hacia atrás como si te sentaras en una silla. Mantén el pecho arriba y la espalda recta. Baja hasta que los muslos queden paralelos al suelo. Empuja con los talones para volver a ponerte de pie en la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/3533-6YUfHPL.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3533-6YUfHPL.gif'),
('3201', 'quarter sit-up', 'waist', 'body weight', 'abs', 'hip flexors', '{"hip flexors"}', 'Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo. Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera. Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que tu torso forme un ángulo de 45 grados. Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/3201-enxnJcM.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3201-enxnJcM.gif'),
('3552', 'quick feet v. 2', 'upper legs', 'body weight', 'quads', 'calves', '{"calves","hamstrings"}', 'Ponte de pie con los pies separados a la altura de los hombros y los brazos a los costados. Comienza moviendo los pies rápidamente hacia arriba y hacia abajo, como si estuvieras corriendo en el sitio. Mantén los movimientos rápidos y ligeros, concentrándote en quedarte sobre la punta de los pies. Continúa durante el tiempo o el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/3552-mweqJin.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3552-mweqJin.gif'),
('0666', 'raise single arm push-up', 'chest', 'body weight', 'pectorals', 'triceps', '{"triceps","shoulders","core"}', 'Comienza en posición de flexión con las manos un poco más separadas que la anchura de los hombros y los pies juntos. Extiende un brazo hacia el lado, paralelo al suelo. Baja el cuerpo hacia el suelo flexionando los codos, manteniendo la espalda recta y el core activado. Empuja de vuelta a la posición inicial, usando los músculos del pecho para elevar el cuerpo. Repite con el otro brazo extendido.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0666-13TpY4H.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0666-13TpY4H.gif'),
('0668', 'rear decline bridge', 'upper legs', 'body weight', 'glutes', 'hamstrings', '{"hamstrings","lower back"}', 'Túmbate boca arriba con los pies planos en el suelo y las rodillas flexionadas. Coloca los brazos a los lados del cuerpo con las palmas hacia abajo. Activa los glúteos y los isquiotibiales, y eleva las caderas del suelo hasta que tu cuerpo forme una línea recta desde las rodillas hasta los hombros. Mantén esta posición durante unos segundos y luego baja lentamente las caderas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0668-UpAlold.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0668-UpAlold.gif'),
('0669', 'rear deltoid stretch', 'shoulders', 'body weight', 'delts', 'trapezius', '{"trapezius","rhomboids"}', 'Ponte de pie con la espalda recta y los pies separados a la altura de los hombros. Extiende el brazo derecho a través del pecho, colocando la mano izquierda sobre el codo derecho. Tira suavemente del brazo derecho hacia el hombro izquierdo, sintiendo un estiramiento en el hombro derecho. Mantén el estiramiento durante 15-30 segundos, luego suelta. Repite del otro lado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0669-xifhB5W.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0669-xifhB5W.gif'),
('0670', 'rear pull-up', 'back', 'body weight', 'lats', 'biceps', '{"biceps","forearms"}', 'Sujeta la barra de dominadas con un agarre prono, un poco más ancho que la altura de los hombros. Cuélgate de la barra con los brazos completamente extendidos y el cuerpo recto. Activa los músculos de la espalda y tira de tu cuerpo hacia arriba, hacia la barra, manteniendo los codos cerca del cuerpo. Continúa subiendo hasta que la barbilla quede por encima de la barra. Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0670-CbFSYC1.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0670-CbFSYC1.gif'),
('1582', 'reclining big toe pose with rope', 'upper legs', 'rope', 'hamstrings', 'calves', '{"calves","glutes"}', 'Túmbate sobre tu espalda con las piernas extendidas y los brazos a los lados. Enrolla la cuerda alrededor de la planta del pie derecho y sujeta los extremos de la cuerda con las manos. Eleva lentamente la pierna derecha hacia el pecho, manteniendo la rodilla recta y el pie flexionado. Mantén el estiramiento durante unos segundos y luego baja lentamente la pierna de vuelta a la posición inicial. Repite con la pierna izquierda. Continúa alternando las piernas durante el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1582-K5xgdvI.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1582-K5xgdvI.gif'),
('3236', 'resistance band hip thrusts on knees (female)', 'upper legs', 'resistance band', 'glutes', 'hamstrings', '{"hamstrings","quadriceps"}', 'Comienza arrodillándote en el suelo con las rodillas separadas a la altura de las caderas y los pies flexionados. Envuelve la banda elástica alrededor de los muslos, justo por encima de las rodillas. Coloca las manos en las caderas o extiéndelas frente a ti para mantener el equilibrio. Activa los glúteos y los músculos del core. Empuja las caderas hacia adelante y aprieta los glúteos mientras levantas las rodillas del suelo, extendiendo las caderas hasta que los muslos queden paralelos al suelo. Mantén la posición por un momento y luego baja lentamente las rodillas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/3236-Pjbc0Kt.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3236-Pjbc0Kt.gif'),
('3007', 'resistance band leg extension', 'upper legs', 'resistance band', 'quads', 'hamstrings', '{"hamstrings"}', 'Sujeta la banda elástica a un punto de anclaje firme y asegúrala alrededor de tu tobillo. Ponte de pie frente al punto de anclaje con los pies separados a la altura de los hombros. Manteniendo el core activado y la parte superior del cuerpo estable, extiende la pierna recta frente a ti. Haz una pausa por un momento en la parte alta y luego vuelve lentamente la pierna a la posición inicial. Repite el número de repeticiones deseado, luego cambia de pierna.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/3007-Y1MsI1l.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3007-Y1MsI1l.gif'),
('3123', 'resistance band seated biceps curl', 'upper arms', 'resistance band', 'biceps', 'forearms', '{"forearms"}', 'Siéntate en una silla o banco con la espalda recta y los pies apoyados en el suelo. Sostén la banda elástica con un agarre supino, con las palmas hacia arriba y los brazos extendidos a los lados del cuerpo. Manteniendo la parte superior de los brazos inmóvil, exhala y flexiona la banda elástica hacia los hombros. Haz una pausa breve en la parte alta, apretando los bíceps. Inhala y baja lentamente la banda elástica de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/3123-XFc3vpY.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3123-XFc3vpY.gif'),
('3124', 'resistance band seated chest press', 'chest', 'resistance band', 'pectorals', 'shoulders', '{"shoulders","triceps"}', 'Siéntate en una silla o banco con la espalda recta y los pies apoyados en el suelo. Sostén las asas de la banda elástica en cada mano, con las palmas hacia abajo y los codos flexionados en un ángulo de 90 grados. Extiende los brazos hacia adelante, alejando la banda elástica de tu pecho. Haz una pausa por un momento al final del movimiento, luego regresa lentamente a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/3124-4x5Okof.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3124-4x5Okof.gif'),
('3006', 'resistance band seated hip abduction', 'upper legs', 'resistance band', 'abductors', 'glutes', '{"glutes","hamstrings"}', 'Siéntate en una silla o banco con la espalda recta y los pies apoyados en el suelo. Envuelve la banda elástica alrededor de los muslos, justo por encima de las rodillas. Coloca las manos en los lados de la silla o el banco para mayor apoyo. Activa los abductores (los músculos externos del muslo) y empuja lentamente las rodillas hacia afuera, contra la resistencia de la banda. Haz una pausa al final del movimiento y luego junta lentamente las rodillas de nuevo. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/3006-0xDpB4L.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3006-0xDpB4L.gif'),
('3122', 'resistance band seated shoulder press', 'shoulders', 'resistance band', 'delts', 'triceps', '{"triceps","upper back"}', 'Siéntate en una silla o banco con la espalda recta y los pies apoyados en el suelo. Sostén la banda elástica con ambas manos, con las palmas hacia adelante, y elévala hasta la altura de los hombros. Empuja la banda por encima de la cabeza, extendiendo completamente los brazos. Haz una pausa por un momento en la parte alta y luego baja lentamente la banda hasta la altura de los hombros. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/3122-S93zLTG.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3122-S93zLTG.gif'),
('3144', 'resistance band seated straight back row', 'back', 'resistance band', 'upper back', 'biceps', '{"biceps","shoulders"}', 'Siéntate en el suelo con las piernas extendidas y enrolla la banda elástica alrededor de los pies. Sostén los extremos de la banda elástica con las manos, con las palmas enfrentadas. Mantén la espalda recta e inclínate ligeramente hacia atrás, activando el core. Tira de la banda elástica hacia el pecho, juntando las escápulas. Haz una pausa por un momento en la parte superior, luego suelta lentamente la tensión y regresa a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/3144-Nu7jqFE.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3144-Nu7jqFE.gif'),
('0872', 'reverse crunch', 'waist', 'body weight', 'abs', 'hip flexors', '{"hip flexors"}', 'Túmbate boca arriba con los brazos extendidos a los lados del cuerpo. Flexiona las rodillas y levanta los pies del suelo, llevando los muslos perpendiculares al suelo. Contrae el abdomen y eleva las caderas del suelo, llevando las rodillas hacia el pecho. Haz una pausa por un momento en la parte superior, luego baja lentamente las caderas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0872-nCU1Ekp.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0872-nCU1Ekp.gif'),
('0672', 'reverse dip', 'upper arms', 'body weight', 'triceps', 'chest', '{"chest","shoulders"}', 'Colócate entre dos barras paralelas con los brazos completamente extendidos y el cuerpo recto. Baja el cuerpo flexionando los codos hasta que los brazos queden paralelos al suelo. Haz una pausa breve, luego empújate de nuevo hacia arriba a la posición inicial estirando los brazos. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0672-NZ5Qqkz.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0672-NZ5Qqkz.gif'),
('0673', 'reverse grip machine lat pulldown', 'back', 'leverage machine', 'lats', 'biceps', '{"biceps","forearms"}', 'Ajusta la altura del asiento y colócate en la máquina con las rodillas debajo de las almohadillas y los pies planos en el suelo. Sujeta las asas con un agarre supino, un poco más separadas que la altura de los hombros. Siéntate erguido con el pecho hacia afuera y los hombros hacia atrás, manteniendo un ligero arco en la zona lumbar. Tira de las asas hacia el pecho, juntando las escápulas. Haz una pausa breve en la parte baja del movimiento, luego suelta lentamente las asas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0673-ecpY0rH.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0673-ecpY0rH.gif'),
('0674', 'reverse grip pull-up', 'back', 'body weight', 'lats', 'biceps', '{"biceps","forearms"}', 'Agarra la barra de dominadas con un agarre supino, con las manos separadas a la altura de los hombros. Cuélgate de la barra con los brazos completamente extendidos y el cuerpo recto. Activa los músculos de la espalda y tira de tu cuerpo hacia la barra, llevando el pecho por delante. Continúa subiendo hasta que la barbilla quede por encima de la barra. Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0674-YAk5dIw.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0674-YAk5dIw.gif'),
('0675', 'reverse hyper extension (on stability ball)', 'upper legs', 'stability ball', 'glutes', 'hamstrings', '{"hamstrings","lower back"}', 'Túmbate boca abajo sobre un balón de estabilidad con las caderas apoyadas en el balón y las piernas extendidas rectas detrás de ti. Coloca las manos en el suelo frente a ti para mayor estabilidad. Activando los glúteos y los isquiotibiales, eleva las piernas hacia el techo tan alto como puedas. Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0675-vM5YS2g.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0675-vM5YS2g.gif'),
('1423', 'reverse hyper on flat bench', 'upper legs', 'body weight', 'glutes', 'hamstrings', '{"hamstrings","lower back"}', 'Túmbate boca abajo en un banco plano con las caderas en el borde y las piernas colgando del banco. Sujétate del banco para mantener la estabilidad. Manteniendo las piernas rectas, elévalas hacia el techo tan alto como puedas. Aprieta los glúteos en la parte alta del movimiento. Baja lentamente las piernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1423-OrETs32.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1423-OrETs32.gif'),
('3663', 'reverse plank with leg lift', 'waist', 'body weight', 'abs', 'glutes', '{"glutes","hamstrings","shoulders"}', 'Siéntate en el suelo con las piernas extendidas frente a ti y las manos apoyadas en el suelo detrás de ti, con los dedos apuntando hacia los pies. Presiona con las manos y levanta las caderas del suelo, llegando a una posición de plancha inversa. Activa el core y levanta una pierna del suelo, extendiéndola recta hacia el techo. Mantén la posición por un momento y luego baja la pierna de nuevo. Repite con la otra pierna. Continúa alternando las piernas durante el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/3663-tFToB7l.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3663-tFToB7l.gif'),
('0677', 'ring dips', 'upper arms', 'body weight', 'triceps', 'chest', '{"chest","shoulders"}', 'Comienza colgándote de las anillas con los brazos completamente extendidos y el cuerpo recto. Baja el cuerpo flexionando los codos hasta que los hombros queden por debajo de los codos. Empújate de vuelta hacia arriba a la posición inicial extendiendo los brazos. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0677-ezTvXcr.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0677-ezTvXcr.gif'),
('2571', 'rocking frog stretch', 'upper legs', 'body weight', 'glutes', 'hamstrings', '{"hamstrings","quadriceps"}', 'Comienza arrodillándote en el suelo con las rodillas separadas a la altura de las caderas. Coloca las manos en el suelo frente a ti para mayor apoyo. Inclínate lentamente hacia adelante, desplazando el peso hacia las manos y extendiendo las piernas detrás de ti. Mantén la espalda recta y activa los glúteos mientras empujas las caderas hacia atrás y hacia arriba en dirección al techo. Mantén esta posición durante unos segundos, sintiendo un estiramiento en los glúteos. Vuelve lentamente a la posición inicial flexionando las rodillas y bajando las caderas de nuevo. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/2571-2Dk4xQV.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/2571-2Dk4xQV.gif'),
('0678', 'rocky pull-up pulldown', 'back', 'body weight', 'lats', 'biceps', '{"biceps","forearms"}', 'Ponte de pie frente a una barra de dominadas con los pies separados a la altura de los hombros. Estira los brazos hacia arriba y agarra la barra con agarre prono, ligeramente más ancho que la altura de los hombros. Cuélgate de la barra con los brazos completamente extendidos y el cuerpo recto. Activa los músculos de la espalda y tira de tu cuerpo hacia la barra, llevando el pecho por delante. Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0678-cQ19bBP.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0678-cQ19bBP.gif'),
('2208', 'roller back stretch', 'back', 'roller', 'spine', 'hamstrings', '{"hamstrings","glutes"}', 'Comienza sentándote en el suelo con las piernas extendidas frente a ti. Coloca el rodillo perpendicular a tu cuerpo, justo debajo de los glúteos. Rueda lentamente el cuerpo hacia atrás, dejando que el rodillo se desplace hacia arriba por tu espalda. Continúa rodando hasta que el rodillo llegue a la parte superior de tu espalda. Haz una pausa por un momento y luego rueda lentamente de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/2208-isofgzg.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/2208-isofgzg.gif'),
('2204', 'roller body saw', 'waist', 'roller', 'abs', 'shoulders', '{"shoulders","triceps","core"}', 'Comienza en posición de plancha con los antebrazos sobre el rodillo y el cuerpo en línea recta. Activa el core y rueda lentamente el rodillo hacia adelante, extendiendo el cuerpo tanto como puedas mientras mantienes el control. Haz una pausa por un momento en el punto más lejano y luego rueda lentamente el rodillo de vuelta hacia tu posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/2204-XeMvLgE.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/2204-XeMvLgE.gif'),
('2205', 'roller hip lat stretch', 'upper legs', 'roller', 'glutes', 'hamstrings', '{"hamstrings","quadriceps"}', 'Comienza arrodillándote en el suelo con el rodillo colocado debajo de las caderas. Coloca las manos sobre el rodillo para mayor apoyo. Rueda lentamente el rodillo hacia adelante, extendiendo las caderas y estirando los glúteos. Mantén el estiramiento durante unos segundos, luego regresa a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/2205-0L2KwtI.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/2205-0L2KwtI.gif'),
('2202', 'roller hip stretch', 'upper legs', 'roller', 'glutes', 'hamstrings', '{"hamstrings","quadriceps"}', 'Comienza sentándote en el suelo con las piernas extendidas frente a ti. Coloca el rodillo debajo de los glúteos, justo por encima de las rodillas. Inclínate hacia atrás y coloca las manos en el suelo detrás de ti para apoyarte. Activa los glúteos y rueda lentamente el rodillo hacia adelante, flexionando las rodillas y llevándolas hacia el pecho. Haz una pausa al final del movimiento, sintiendo un estiramiento en los glúteos. Rueda lentamente el rodillo de vuelta a la posición inicial, extendiendo las piernas. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/2202-oMypNrz.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/2202-oMypNrz.gif'),
('2206', 'roller reverse crunch', 'waist', 'roller', 'abs', 'hip flexors', '{"hip flexors"}', 'Túmbate boca arriba con los brazos extendidos rectos por encima de la cabeza y las piernas rectas frente a ti. Coloca el rodillo entre los pies y sujétalo con los dedos de los pies. Activando el abdomen, levanta las piernas del suelo y flexiona las rodillas hacia el pecho, rodando el rodillo hacia tu cuerpo. Haz una pausa por un momento en la parte alta y luego baja lentamente las piernas de vuelta a la posición inicial, rodando el rodillo alejándolo de tu cuerpo. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/2206-SKXQAx3.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/2206-SKXQAx3.gif'),
('2203', 'roller seated shoulder flexor depresor retractor', 'chest', 'roller', 'pectorals', 'deltoids', '{"deltoids","triceps"}', 'Siéntate sobre una superficie plana con las piernas extendidas frente a ti. Sostén el rodillo con ambas manos, con las palmas hacia abajo, y colócalo sobre tus muslos. Inclínate ligeramente hacia delante y aleja el rodillo de tu cuerpo, extendiendo los brazos rectos frente a ti. Haz una pausa por un momento, luego rueda el rodillo lentamente de vuelta hacia tu cuerpo, doblando los brazos y trayéndolo de nuevo hacia los muslos. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/2203-8coXSYU.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/2203-8coXSYU.gif'),
('2209', 'roller seated single leg shoulder flexor depresor retractor', 'chest', 'roller', 'pectorals', 'deltoids', '{"deltoids","triceps"}', 'Siéntate sobre una superficie plana con las piernas extendidas frente a ti. Sostén el rodillo con ambas manos, con las palmas hacia abajo, y colócalo sobre tus muslos. Inclínate ligeramente hacia atrás y contrae los músculos del core. Eleva el rodillo hasta la altura de los hombros, manteniendo los brazos rectos. Baja lentamente el rodillo de nuevo hacia los muslos. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/2209-CjETvlw.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/2209-CjETvlw.gif'),
('2207', 'roller side lat stretch', 'back', 'roller', 'lats', 'shoulders', '{"shoulders","triceps"}', 'Ponte de pie con los pies separados a la altura de los hombros y sujeta el rodillo con ambas manos frente al cuerpo. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta. Extiende los brazos hacia delante y rueda el rodillo hacia los pies, sintiendo un estiramiento en los dorsales. Mantén el estiramiento durante unos segundos, luego rueda el rodillo lentamente de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/2207-c3Pfhti.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/2207-c3Pfhti.gif'),
('0680', 'rope climb', 'back', 'rope', 'upper back', 'forearms', '{"forearms","biceps","shoulders"}', 'Ponte de pie frente a la cuerda con los pies separados a la altura de los hombros. Sujeta la cuerda con ambas manos, con las palmas mirando hacia ti. Flexiona ligeramente las rodillas y activa el core. Comienza a subir por la cuerda alternando los movimientos de las manos. Usa las piernas para ayudar en el movimiento ascendente. Continúa trepando hasta alcanzar la altura deseada o la parte superior de la cuerda. Para descender, invierte el movimiento alterno de las manos mientras controlas tu descenso. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0680-yaAxcQr.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0680-yaAxcQr.gif'),
('0685', 'run', 'cardio', 'body weight', 'cardiovascular system', 'quadriceps', '{"quadriceps","hamstrings","calves"}', 'Comienza de pie con los pies separados a la altura de la cadera. Activa el core y mantén la parte superior del cuerpo relajada. Comienza a trotar en el lugar, levantando las rodillas hacia el pecho y aterrizando suavemente sobre la punta de los pies. Mantén un ritmo constante y continúa trotando durante la duración o distancia deseada. Recuerda respirar profundamente y mantener una buena postura durante todo el ejercicio.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0685-oLrKqDH.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0685-oLrKqDH.gif'),
('0684', 'run (equipment)', 'cardio', 'body weight', 'cardiovascular system', 'quadriceps', '{"quadriceps","hamstrings","calves"}', 'Comienza de pie con los pies separados a la altura de la cadera. Activa el core y mantén la parte superior del cuerpo relajada. Comienza a trotar en el lugar, levantando las rodillas hacia el pecho y aterrizando suavemente sobre la punta de los pies. Mantén un ritmo constante y continúa trotando durante la duración o distancia deseada. Recuerda respirar profundamente y mantener una buena postura durante todo el ejercicio.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0684-y5p0H8a.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0684-y5p0H8a.gif'),
('1585', 'runners stretch', 'upper legs', 'body weight', 'hamstrings', 'calves', '{"calves","quadriceps"}', 'Ponte de pie con los pies separados a la altura de la cadera. Da un paso hacia delante con el pie derecho, manteniendo el pie izquierdo firme en el suelo. Dobla la rodilla derecha y baja el cuerpo, manteniendo la pierna izquierda recta. Coloca las manos sobre el muslo derecho para apoyarte. Mantén el estiramiento durante 20-30 segundos, luego cambia de lado y repite.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1585-0mB6wHO.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1585-0mB6wHO.gif'),
('0687', 'russian twist', 'waist', 'body weight', 'abs', 'obliques', '{"obliques"}', 'Siéntate en el suelo con las rodillas flexionadas y los pies apoyados en el suelo. Inclínate ligeramente hacia atrás manteniendo la espalda recta y el core activado. Junta las manos frente al pecho o sujeta una pesa si lo deseas. Levanta los pies del suelo, equilibrándote sobre los isquiones. Gira el torso hacia la derecha, llevando las manos o la pesa hacia el lado derecho del cuerpo. Haz una pausa por un momento, luego gira el torso hacia la izquierda, llevando las manos o la pesa hacia el lado izquierdo del cuerpo. Continúa alternando lados durante el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0687-XVDdcoj.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0687-XVDdcoj.gif'),
('3012', 'scapula dips', 'back', 'body weight', 'traps', 'rhomboids', '{"rhomboids","deltoids"}', 'Comienza de pie con los pies separados a la altura de los hombros y los brazos extendidos frente a ti. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta. Baja el cuerpo doblando los codos y retrayendo las escápulas, como si intentaras apretar un lápiz entre ellas. Haz una pausa por un momento en la posición baja, luego empuja con las manos para extender los codos y volver a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/3012-7xeukSt.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3012-7xeukSt.gif'),
('3021', 'scapula push-up', 'chest', 'body weight', 'serratus anterior', 'triceps', '{"triceps","shoulders"}', 'Comienza en una posición de plancha alta con las manos justo debajo de los hombros y el cuerpo en línea recta. Baja el pecho hacia el suelo, manteniendo los codos cerca del cuerpo. A medida que bajas, junta las escápulas y empuja el pecho hacia delante. Haz una pausa por un momento en la posición baja, luego empuja de nuevo hacia arriba hasta la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/3021-jV65tKx.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3021-jV65tKx.gif'),
('0688', 'scapular pull-up', 'back', 'body weight', 'traps', 'biceps', '{"biceps","rhomboids","rear deltoids"}', 'Comienza colgándote de una barra de dominadas con las palmas hacia afuera y los brazos completamente extendidos. Retrae las escápulas llevándolas hacia abajo y atrás. Activa los músculos de la espalda y tira de tu cuerpo hacia la barra, enfocándote en juntar las escápulas. Haz una pausa breve en la parte superior del movimiento, luego baja lentamente el cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0688-uTBt1HV.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0688-uTBt1HV.gif'),
('3219', 'scissor jumps (male)', 'cardio', 'body weight', 'cardiovascular system', 'quadriceps', '{"quadriceps","hamstrings","calves"}', 'Ponte de pie con los pies separados a la altura de los hombros. Salta del suelo y al mismo tiempo cruza la pierna derecha por delante de la pierna izquierda. Al aterrizar, cambia rápidamente de pierna, cruzando la pierna izquierda por delante de la pierna derecha. Continúa alternando las piernas y saltando lo más rápido posible. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/3219-Eh2v5Iu.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3219-Eh2v5Iu.gif'),
('1390', 'seated calf stretch (male)', 'lower legs', 'body weight', 'calves', 'hamstrings', '{"hamstrings"}', 'Siéntate en el borde de una silla o banco con los pies planos sobre el suelo. Extiende una pierna recta frente a ti, manteniendo el talón en el suelo. Inclínate ligeramente hacia delante, sintiendo un estiramiento en la pantorrilla. Mantén el estiramiento durante 20-30 segundos. Cambia de pierna y repite el estiramiento.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1390-17bqEXD.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1390-17bqEXD.gif'),
('1424', 'seated glute stretch', 'upper legs', 'body weight', 'glutes', 'hamstrings', '{"hamstrings"}', 'Siéntate en el suelo con las piernas extendidas frente a ti. Dobla la rodilla derecha y cruza el tobillo derecho sobre el muslo izquierdo. Coloca la mano derecha en el suelo detrás de ti para apoyarte. Con la mano izquierda, presiona suavemente la rodilla derecha para profundizar el estiramiento. Mantén el estiramiento durante 30 segundos a 1 minuto. Cambia de lado y repite.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1424-DeDThfG.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1424-DeDThfG.gif'),
('0689', 'seated leg raise', 'waist', 'body weight', 'abs', 'hip flexors', '{"hip flexors"}', 'Siéntate en un banco plano con la espalda recta y los pies planos sobre el suelo. Coloca las manos a los lados del banco para apoyarte. Manteniendo las piernas rectas, levántalas lentamente frente a ti hasta que queden paralelas al suelo. Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0689-Hgs6Nl1.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0689-Hgs6Nl1.gif'),
('0690', 'seated lower back stretch', 'back', 'body weight', 'lats', 'glutes', '{"glutes","hamstrings"}', 'Siéntate en el borde de una silla con los pies planos sobre el suelo. Coloca las manos sobre los muslos o a los lados de la silla para apoyarte. Inclínate lentamente hacia delante desde la cadera, manteniendo la espalda recta. Siente el estiramiento en la zona lumbar y mantén la posición durante 20-30 segundos. Regresa lentamente a la posición inicial y repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0690-QFmz6ch.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0690-QFmz6ch.gif'),
('2567', 'seated piriformis stretch', 'upper legs', 'body weight', 'glutes', 'hamstrings', '{"hamstrings"}', 'Siéntate en el suelo con las piernas extendidas frente a ti. Dobla la rodilla derecha y coloca el pie derecho en la parte exterior de la rodilla izquierda. Coloca el codo izquierdo en la parte exterior de la rodilla derecha y gira suavemente el torso hacia la derecha. Mantén el estiramiento durante 20-30 segundos, luego cambia de lado y repite.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/2567-QY39eBr.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/2567-QY39eBr.gif'),
('0691', 'seated side crunch (wall)', 'waist', 'body weight', 'abs', 'obliques', '{"obliques"}', 'Siéntate en el suelo con la espalda contra una pared y las piernas extendidas frente a ti. Dobla las rodillas y coloca los pies planos sobre el suelo, separados a la altura de la cadera. Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera. Contrae el abdomen e inclínate hacia un lado, llevando el codo hacia la cadera. Haz una pausa breve y luego vuelve a la posición inicial. Repite del otro lado. Continúa alternando lados durante el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0691-Y9hNPcN.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0691-Y9hNPcN.gif'),
('1587', 'seated wide angle pose sequence', 'upper legs', 'body weight', 'hamstrings', 'quadriceps', '{"quadriceps","calves"}', 'Siéntate en el suelo con las piernas extendidas formando un ángulo amplio. Flexiona los pies y contrae los cuádriceps. Coloca las manos en el suelo detrás de ti para apoyarte. Manteniendo la espalda recta, inclínate hacia delante desde la cadera. Continúa inclinándote hacia delante hasta sentir un estiramiento en los isquiotibiales. Mantén esta posición durante unas cuantas respiraciones. Libera lentamente el estiramiento y vuelve a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1587-HIgYKAB.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1587-HIgYKAB.gif'),
('0697', 'self assisted inverse leg curl', 'upper legs', 'body weight', 'hamstrings', 'glutes', '{"glutes","calves"}', 'Túmbate boca arriba sobre una esterilla o banco con las piernas extendidas. Coloca las manos a los lados o debajo de los glúteos para apoyarte. Dobla las rodillas y levanta los pies del suelo, llevando los muslos hacia el pecho. Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0697-GwYwElT.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0697-GwYwElT.gif'),
('1766', 'self assisted inverse leg curl', 'upper legs', 'body weight', 'hamstrings', 'glutes', '{"glutes","calves"}', 'Túmbate boca abajo en una máquina de curl femoral con las piernas extendidas y los tobillos enganchados bajo la palanca acolchada. Coloca las manos en las asas laterales de la máquina para apoyarte. Manteniendo la parte superior del cuerpo inmóvil, exhala y flexiona las piernas hacia arriba lo más posible. Mantén la posición contraída durante una pausa breve mientras aprietas los isquiotibiales. Baja lentamente las piernas de vuelta a la posición inicial mientras inhalas. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1766-ZSY3MsL.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1766-ZSY3MsL.gif'),
('0696', 'self assisted inverse leg curl (on floor)', 'upper legs', 'body weight', 'hamstrings', 'glutes', '{"glutes","calves"}', 'Túmbate sobre tu espalda con las piernas extendidas y los brazos a los lados. Dobla las rodillas y coloca los pies planos sobre el suelo, separados a la altura de la cadera. Levanta las caderas del suelo, activando los glúteos y los isquiotibiales. Flexiona lentamente las piernas hacia los glúteos, manteniendo las caderas elevadas. Haz una pausa breve en la parte superior, luego extiende lentamente las piernas de vuelta a la posición inicial. Baja las caderas de nuevo hacia el suelo. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0696-E4PwJqI.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0696-E4PwJqI.gif'),
('3222', 'semi squat jump (male)', 'cardio', 'body weight', 'cardiovascular system', 'quadriceps', '{"quadriceps","hamstrings","calves"}', 'Ponte de pie con los pies separados a la altura de los hombros. Flexiona las rodillas y baja el cuerpo hacia una posición de sentadilla. Salta de forma explosiva, extendiendo las caderas y las rodillas mientras balanceas los brazos para generar impulso. Aterriza suavemente sobre la punta de los pies y pasa de inmediato a la siguiente repetición. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/3222-6FMU51h.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3222-6FMU51h.gif'),
('3656', 'short stride run', 'cardio', 'body weight', 'cardiovascular system', 'quadriceps', '{"quadriceps","hamstrings","calves"}', 'Busca un espacio abierto o una cinta de correr para realizar el ejercicio. Ponte de pie con los pies separados a la altura de la cadera. Comienza a trotar en el lugar, levantando las rodillas alto y moviendo los brazos. Después de unos segundos, comienza a dar pasos cortos hacia delante, manteniendo un ritmo rápido. Continúa corriendo con pasos cortos durante la duración o distancia deseada.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/3656-CcWEoWV.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3656-CcWEoWV.gif'),
('1763', 'shoulder grip pull-up', 'back', 'body weight', 'lats', 'biceps', '{"biceps","forearms"}', 'Sujeta la barra de dominadas con un agarre a la altura de los hombros, con las palmas mirando hacia fuera. Cuélgate libremente con los brazos completamente extendidos. Activa los músculos de la espalda y tira de tu cuerpo hacia la barra hasta que la barbilla quede por encima de ella. Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1763-YtgD7Xq.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1763-YtgD7Xq.gif'),
('3699', 'shoulder tap', 'waist', 'body weight', 'abs', 'shoulders', '{"shoulders","triceps"}', 'Comienza en una posición de plancha alta con las manos justo debajo de los hombros y el cuerpo en línea recta. Activa el core y levanta la mano derecha del suelo, extendiéndola para tocar el hombro izquierdo. Coloca la mano derecha de nuevo en el suelo y repite tocando el hombro derecho con la mano izquierda. Continúa alternando los toques de hombro mientras mantienes las caderas y el torso estables. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/3699-yRpV5TC.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3699-yRpV5TC.gif'),
('0699', 'shoulder tap push-up', 'chest', 'body weight', 'pectorals', 'triceps', '{"triceps","core"}', 'Comienza en una posición de plancha alta con las manos un poco más separadas que la anchura de los hombros y el cuerpo en línea recta desde la cabeza hasta los talones. Baja el cuerpo hacia el suelo flexionando los codos, manteniéndolos cerca de los costados. Mientras empujas hacia arriba, levanta la mano derecha del suelo y toca el hombro izquierdo. Vuelve a colocar la mano derecha en el suelo y repite la flexión, esta vez levantando la mano izquierda y tocando el hombro derecho. Continúa alternando los toques de hombro en cada repetición de la flexión. Mantén el core estable y evita una rotación excesiva de la cadera durante todo el ejercicio. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0699-qEse6fe.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0699-qEse6fe.gif'),
('1774', 'side bridge hip abduction', 'upper legs', 'body weight', 'abductors', 'glutes', '{"glutes","obliques"}', 'Túmbate de lado con las piernas extendidas y una sobre la otra. Apóyate sobre el antebrazo, manteniendo el codo directamente debajo del hombro. Activa el core y levanta las caderas del suelo, formando una línea recta desde la cabeza hasta los pies. Manteniendo el core activado, levanta la pierna superior lo más alto posible sin rotar las caderas. Haz una pausa por un momento en la posición alta, luego baja la pierna de nuevo. Repite el número de repeticiones deseado, luego cambia de lado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1774-WL4EmxJ.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1774-WL4EmxJ.gif'),
('0705', 'side bridge v. 2', 'waist', 'body weight', 'abs', 'obliques', '{"obliques","glutes"}', 'Túmbate de lado con las piernas extendidas y una sobre la otra. Coloca el antebrazo en el suelo justo debajo del hombro, con el codo flexionado en un ángulo de 90 grados. Activa el core y levanta las caderas del suelo, formando una línea recta desde la cabeza hasta los pies. Mantén esta posición durante el tiempo deseado. Baja las caderas de vuelta a la posición inicial. Repite del otro lado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0705-RKjH6Lt.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0705-RKjH6Lt.gif'),
('0709', 'side hip (on parallel bars)', 'waist', 'body weight', 'abs', 'obliques', '{"obliques","hip flexors"}', 'Ponte de pie entre dos barras paralelas con los pies separados a la altura de los hombros. Coloca las manos sobre las barras y levanta el cuerpo del suelo, apoyando tu peso en los brazos. Contrae el abdomen y levanta lentamente las piernas hacia el lado, manteniéndolas rectas. Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0709-jTkSc6o.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0709-jTkSc6o.gif'),
('0710', 'side hip abduction', 'upper legs', 'body weight', 'abductors', 'glutes', '{"glutes","quadriceps"}', 'Ponte de pie con los pies separados a la altura de los hombros y las manos en las caderas. Traslada el peso a una pierna y levanta la pierna opuesta hacia el lado, manteniéndola recta. Haz una pausa por un momento en la posición alta, luego baja lentamente la pierna de nuevo a la posición inicial. Repite del otro lado. Continúa alternando lados durante el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0710-7WaDzyL.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0710-7WaDzyL.gif'),
('1358', 'side lying floor stretch', 'back', 'body weight', 'lats', 'obliques', '{"obliques","glutes"}', 'Túmbate de lado con las piernas rectas y el brazo de abajo extendido recto por encima de la cabeza. Dobla la rodilla de arriba y coloca el pie en el suelo frente a la pierna de abajo. Extiende el brazo de arriba por encima de la cabeza y agárrate a algo estable, como una pared o un mueble. Levanta lentamente la pierna de abajo del suelo, manteniéndola recta, hasta sentir un estiramiento en el costado. Mantén el estiramiento durante 20-30 segundos, luego baja lentamente la pierna de nuevo. Repite del otro lado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1358-jDOKRM5.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1358-jDOKRM5.gif'),
('3667', 'side lying hip adduction (male)', 'upper legs', 'body weight', 'adductors', 'glutes', '{"glutes","hamstrings"}', 'Túmbate de lado con las piernas rectas y apiladas una sobre la otra. Coloca el brazo de abajo bajo la cabeza para apoyarte. Activa los aductores y levanta la pierna de arriba lo más alto posible sin rotar las caderas ni inclinarte hacia atrás. Haz una pausa por un momento en la posición alta, luego baja lentamente la pierna de nuevo a la posición inicial. Repite el número de repeticiones deseado, luego cambia de lado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/3667-c8f5cSY.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3667-c8f5cSY.gif'),
('1775', 'side plank hip adduction', 'upper legs', 'body weight', 'adductors', 'obliques', '{"obliques","glutes"}', 'Comienza tumbado de lado con las piernas extendidas y apiladas una sobre la otra. Apóyate sobre el antebrazo, manteniendo el codo directamente debajo del hombro. Activa el core y levanta las caderas del suelo, formando una línea recta desde la cabeza hasta los pies. Manteniendo la posición de plancha lateral, levanta la pierna de arriba hacia el techo, manteniéndola recta. Baja lentamente la pierna de nuevo a la posición inicial. Repite el número de repeticiones deseado, luego cambia de lado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1775-VO2qeJg.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1775-VO2qeJg.gif'),
('0716', 'side push neck stretch', 'neck', 'body weight', 'levator scapulae', 'trapezius', '{"trapezius","sternocleidomastoid"}', 'Ponte de pie o siéntate erguido con los hombros relajados. Inclina la cabeza hacia la derecha, llevando la oreja derecha hacia el hombro derecho. Coloca la mano derecha en el lado izquierdo de la cabeza y aplica una presión suave para aumentar el estiramiento. Mantén el estiramiento durante 15-30 segundos. Repite hacia el otro lado, inclinando la cabeza hacia la izquierda y aplicando presión con la mano izquierda. Repite el estiramiento 2-3 veces en cada lado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0716-oQRJYkC.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0716-oQRJYkC.gif'),
('0717', 'side push-up', 'upper arms', 'body weight', 'triceps', 'shoulders', '{"shoulders","chest","core"}', 'Comienza tumbado de lado con las piernas extendidas y apiladas una sobre la otra. Coloca la mano de abajo en el suelo directamente debajo del hombro, con los dedos apuntando hacia delante. Empuja con la mano de abajo para levantar el cuerpo del suelo, manteniendo las piernas rectas y el core activado. Extiende el brazo de arriba recto hacia el techo, formando una línea recta desde la cabeza hasta los talones. Baja el cuerpo de nuevo a la posición inicial con control. Repite el número de repeticiones deseado, luego cambia de lado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0717-wpbD28t.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0717-wpbD28t.gif'),
('0721', 'side wrist pull stretch', 'lower arms', 'body weight', 'forearms', 'wrists', '{"wrists","hands"}', 'Ponte de pie con los pies separados a la altura de los hombros y los brazos extendidos frente a ti. Extiende el brazo derecho hacia el lado, paralelo al suelo, con la palma hacia abajo. Con la mano izquierda, sujeta la mano derecha y tira de ella suavemente hacia tu cuerpo, sintiendo un estiramiento en el antebrazo derecho. Mantén el estiramiento durante 15-30 segundos, luego suelta. Repite del otro lado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0721-UtmIqcI.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0721-UtmIqcI.gif'),
('0720', 'side-to-side chin', 'back', 'body weight', 'lats', 'biceps', '{"biceps","forearms"}', 'Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas. Sujeta una barra de dominadas con un agarre prono, con las manos un poco más separadas que el ancho de los hombros. Cuélgate de la barra con los brazos completamente extendidos y el cuerpo relajado. Levántate doblando los codos y llevando la barbilla hacia la barra, manteniendo el cuerpo recto. Una vez que la barbilla esté por encima de la barra, bájate de nuevo a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0720-isAAZWA.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0720-isAAZWA.gif'),
('3213', 'side-to-side toe touch (male)', 'waist', 'body weight', 'abs', 'obliques', '{"obliques","hip flexors"}', 'Ponte de pie con los pies separados a la altura de los hombros y los brazos extendidos hacia los lados. Dobla la cintura hacia la derecha, llevando la mano derecha hacia el pie derecho mientras mantienes la mano izquierda extendida hacia el lado. Vuelve a la posición inicial y luego dobla la cintura hacia la izquierda, llevando la mano izquierda hacia el pie izquierdo mientras mantienes la mano derecha extendida hacia el lado. Repite el movimiento de flexión lateral el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/3213-WCAvOfC.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3213-WCAvOfC.gif'),
('0725', 'single arm push-up', 'chest', 'body weight', 'pectorals', 'triceps', '{"triceps","shoulders","core"}', 'Comienza en posición de flexión con las manos separadas a la altura de los hombros y una mano colocada un poco más ancha que la otra. Activa el core y baja el cuerpo hacia el suelo flexionando los codos, manteniendo la espalda recta. Al bajar, traslada el peso hacia un lado y levanta el brazo opuesto del suelo, extendiéndolo recto hacia el lado. Empuja con el pecho y los tríceps para subir el cuerpo de nuevo a la posición inicial, mientras bajas simultáneamente el brazo extendido de vuelta al suelo. Repite el movimiento, alternando el brazo que extiendes en cada repetición.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0725-MUic5zN.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0725-MUic5zN.gif'),
('3645', 'single leg bridge with outstretched leg', 'upper legs', 'body weight', 'glutes', 'hamstrings', '{"hamstrings","quadriceps"}', 'Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo. Extiende una pierna recta hacia delante. Activa los glúteos y levanta las caderas del suelo, formando una línea recta desde las rodillas hasta los hombros. Mantén la posición alta por un momento, luego baja lentamente las caderas de nuevo a la posición inicial. Repite el número de repeticiones deseado, luego cambia de pierna.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/3645-rmEukuS.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3645-rmEukuS.gif'),
('0727', 'single leg calf raise (on a dumbbell)', 'lower legs', 'dumbbell', 'calves', 'ankles', '{"ankles","feet"}', 'Ponte de pie con los pies separados a la altura de la cadera y sujeta una mancuerna en una mano. Levanta un pie del suelo y mantén el equilibrio sobre el otro pie. Eleva lentamente el talón lo más alto posible, usando los músculos de la pantorrilla. Haz una pausa por un momento en la parte superior, luego baja lentamente el talón de vuelta hacia abajo. Repite el número de repeticiones deseado, luego cambia a la otra pierna.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0727-fKZgDEO.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0727-fKZgDEO.gif'),
('0730', 'single leg platform slide', 'upper legs', 'body weight', 'hamstrings', 'glutes', '{"glutes","quadriceps"}', 'Comienza de pie con un pie sobre una plataforma o tabla deslizante. Dobla ligeramente la rodilla y desliza el pie sobre la plataforma hacia atrás, extendiendo la pierna. Mantén el core activado y conserva una postura recta durante todo el movimiento. Vuelve lentamente a la posición inicial deslizando el pie de regreso a la posición inicial. Repite el movimiento el número de repeticiones deseado y luego cambia de pierna.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0730-LNE3wfo.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0730-LNE3wfo.gif'),
('1759', 'single leg squat (pistol) male', 'upper legs', 'body weight', 'glutes', 'quadriceps', '{"quadriceps","hamstrings","calves"}', 'Ponte de pie con los pies separados a la altura de los hombros y los brazos extendidos frente a ti. Levanta el pie derecho del suelo y extiéndelo hacia delante. Baja lentamente el cuerpo doblando la rodilla izquierda y empujando las caderas hacia atrás. Mantén el pecho elevado y la espalda recta mientras bajas el cuerpo. Baja hasta que el muslo izquierdo quede paralelo al suelo, o lo más abajo que puedas llegar cómodamente. Haz una pausa por un momento en la posición baja, luego empuja con el talón izquierdo para volver a la posición inicial. Repite el número de repeticiones deseado, luego cambia de pierna.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1759-nqs5HGV.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1759-nqs5HGV.gif'),
('1489', 'sissy squat', 'upper legs', 'body weight', 'quads', 'calves', '{"calves","glutes"}', 'Ponte de pie con los pies separados a la altura de los hombros y los dedos de los pies ligeramente hacia afuera. Sujétate de un objeto estable para mantener el equilibrio si es necesario. Baja lentamente el cuerpo doblando las rodillas e inclinándote hacia atrás, manteniendo el torso erguido. Continúa bajando hasta que los muslos queden paralelos al suelo o tan lejos como puedas llegar cómodamente. Haz una pausa breve y luego empuja con los talones para volver a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1489-xdYPUtE.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1489-xdYPUtE.gif'),
('0735', 'sit-up v. 2', 'waist', 'body weight', 'abs', 'hip flexors', '{"hip flexors"}', 'Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo. Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera. Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que tu torso forme un ángulo de 45 grados. Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0735-Bn6TXyO.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0735-Bn6TXyO.gif'),
('3679', 'sit-up with arms on chest', 'waist', 'body weight', 'abs', 'hip flexors', '{"hip flexors"}', 'Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo. Cruza los brazos sobre el pecho. Contrayendo el abdomen, levanta la parte superior del cuerpo del suelo hacia las rodillas. Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/3679-6ZCiYWQ.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3679-6ZCiYWQ.gif'),
('3361', 'skater hops', 'cardio', 'body weight', 'cardiovascular system', 'quadriceps', '{"quadriceps","hamstrings","glutes","calves"}', 'Ponte de pie con los pies separados a la altura de los hombros. Dobla ligeramente las rodillas y salta hacia la derecha, aterrizando sobre el pie derecho. Al aterrizar, balancea la pierna izquierda detrás de la pierna derecha y toca el suelo con los dedos del pie izquierdo. Salta inmediatamente hacia la izquierda, aterrizando sobre el pie izquierdo. Al aterrizar, balancea la pierna derecha detrás de la pierna izquierda y toca el suelo con los dedos del pie derecho. Continúa alternando los lados, saltando y tocando el suelo con cada pierna. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/3361-zfNHMN9.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3361-zfNHMN9.gif'),
('2142', 'ski ergometer', 'upper arms', 'skierg machine', 'triceps', 'shoulders', '{"shoulders","forearms"}', 'Ajusta la altura del asiento y los apoyapiés a una posición cómoda. Sujeta las agarraderas con un agarre prono, con las palmas hacia abajo. Siéntate erguido con los pies planos sobre los apoyapiés. Extiende los brazos rectos frente a ti, manteniendo los codos ligeramente flexionados. Activa los tríceps y empuja las asas hacia abajo, hacia los muslos. Haz una pausa por un momento en la parte inferior, luego regresa lentamente a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/2142-vpQaQkH.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/2142-vpQaQkH.gif'),
('3671', 'ski step', 'cardio', 'body weight', 'cardiovascular system', 'quadriceps', '{"quadriceps","hamstrings","glutes","calves"}', 'Ponte de pie con los pies separados a la altura de los hombros. Dobla ligeramente las rodillas y mantén la espalda recta. Salta hacia la derecha, aterrizando sobre el pie derecho mientras balanceas la pierna izquierda detrás de la pierna derecha. Salta inmediatamente hacia la izquierda, aterrizando sobre el pie izquierdo mientras balanceas la pierna derecha detrás de la pierna izquierda. Continúa alternando los saltos de lado a lado, imitando un movimiento de esquí. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/3671-5MRH8H2.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3671-5MRH8H2.gif'),
('3304', 'skin the cat', 'back', 'body weight', 'upper back', 'shoulders', '{"shoulders","core"}', 'Comienza colgándote de una barra con los brazos completamente extendidos y el cuerpo relajado. Activa el core y levanta las piernas, llevando las rodillas hacia el pecho. Continúa levantando las piernas por encima de la cabeza, permitiendo que el cuerpo pase entre los brazos. Una vez que las piernas estén completamente extendidas por encima de la cabeza, comienza a bajarlas de nuevo hacia la posición inicial. Mientras bajas las piernas, permite que el cuerpo pase de nuevo entre los brazos hasta quedar colgado con los brazos completamente extendidos otra vez. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/3304-MSfvriJ.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3304-MSfvriJ.gif'),
('1425', 'sled 45 degrees one leg press', 'upper legs', 'sled machine', 'glutes', 'quadriceps', '{"quadriceps","hamstrings","calves"}', 'Ajusta la máquina de trineo a un ángulo de 45 grados. Siéntate en la máquina de trineo con la espalda contra el respaldo y los pies sobre la placa. Coloca un pie sobre la placa y extiende la pierna, empujando el trineo alejándolo de ti. Dobla lentamente la rodilla y baja el trineo de vuelta a la posición inicial. Repite con la otra pierna. Continúa alternando las piernas durante el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1425-WWD6FzI.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1425-WWD6FzI.gif'),
('0738', 'sled 45в° calf press', 'lower legs', 'sled machine', 'calves', 'hamstrings', '{"hamstrings"}', 'Ajusta la máquina de trineo a un ángulo de 45 grados. Coloca los pies sobre la plataforma del trineo con los dedos de los pies apuntando hacia delante. Empuja la plataforma del trineo alejándola de ti extendiendo los tobillos y las pantorrillas. Haz una pausa por un momento en la posición alta, luego baja lentamente la plataforma del trineo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0738-qCNVnaU.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0738-qCNVnaU.gif'),
('0739', 'sled 45в° leg press', 'upper legs', 'sled machine', 'glutes', 'quadriceps', '{"quadriceps","hamstrings","calves"}', 'Ajusta el asiento y la placa de la máquina de trineo a una posición cómoda. Siéntate en la máquina de trineo con la espalda contra el respaldo y los pies separados a la altura de los hombros sobre la placa. Sujeta las asas a los lados del asiento para mayor estabilidad. Empuja la placa alejándola de tu cuerpo extendiendo las piernas, manteniendo los talones sobre la placa. Continúa empujando hasta que las piernas estén casi completamente extendidas, pero sin bloquear las rodillas. Haz una pausa por un momento en la parte alta del movimiento, luego baja lentamente la placa de vuelta hacia tu cuerpo doblando las rodillas. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0739-10Z2DXU.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0739-10Z2DXU.gif'),
('1464', 'sled 45в° leg press (back pov)', 'upper legs', 'sled machine', 'glutes', 'quadriceps', '{"quadriceps","hamstrings","calves"}', 'Ajusta el asiento de la máquina de trineo de modo que las rodillas queden en un ángulo de 45 grados. Siéntate en la máquina de trineo con la espalda contra el respaldo y los pies separados a la altura de los hombros sobre la placa. Sujeta las asas a los lados del asiento para mayor estabilidad. Empuja la placa alejándola de tu cuerpo extendiendo las piernas, manteniendo los talones sobre la placa. Haz una pausa por un momento en la posición completamente extendida. Dobla lentamente las rodillas y baja la placa de vuelta hacia tu cuerpo, controlando el movimiento. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1464-yn2lLSI.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1464-yn2lLSI.gif'),
('1463', 'sled 45° leg press (side pov)', 'upper legs', 'sled machine', 'glutes', 'quadriceps', '{"quadriceps","hamstrings","calves"}', 'Ajusta el asiento de la máquina de trineo de modo que las rodillas queden en un ángulo de 90 grados cuando los pies estén sobre la placa. Siéntate en la máquina de trineo con la espalda plana contra el respaldo y los pies separados a la altura de los hombros sobre la placa. Sujeta las asas a los lados del asiento para mayor estabilidad. Empuja contra la placa para extender las piernas, estirándolas por completo. Haz una pausa por un momento en la posición alta, luego dobla lentamente las rodillas para bajar la placa de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1463-2Qh2J1e.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1463-2Qh2J1e.gif'),
('0740', 'sled 45в° leg wide press', 'upper legs', 'sled machine', 'glutes', 'quadriceps', '{"quadriceps","hamstrings","calves"}', 'Ajusta la máquina de trineo a un ángulo de 45 grados. Siéntate en la máquina de trineo con la espalda contra el respaldo y los pies sobre la plataforma. Coloca los pies más separados que el ancho de los hombros. Empuja contra la plataforma para extender las piernas y enderezar las rodillas. Haz una pausa por un momento al final del movimiento, luego dobla lentamente las rodillas para volver a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0740-tj41Nu6.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0740-tj41Nu6.gif'),
('1391', 'sled calf press on leg press', 'lower legs', 'sled machine', 'calves', 'hamstrings', '{"hamstrings","quadriceps"}', 'Ajusta el asiento de la máquina de prensa de piernas de modo que las rodillas queden ligeramente flexionadas cuando los pies estén sobre el trineo. Coloca los pies separados a la altura de los hombros sobre el trineo, con los dedos de los pies apuntando hacia delante. Suelta las asas de seguridad y empuja el trineo alejándolo de ti extendiendo las rodillas y los tobillos. Haz una pausa por un momento en la parte alta del movimiento, luego baja lentamente el trineo doblando las rodillas y los tobillos. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1391-ykHcWme.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1391-ykHcWme.gif'),
('0741', 'sled closer hack squat', 'upper legs', 'sled machine', 'glutes', 'quadriceps', '{"quadriceps","hamstrings","calves"}', 'Ajusta la máquina de trineo a un peso cómodo y colócate con la espalda contra el respaldo. Coloca los pies separados a la altura de los hombros sobre la plataforma, con los dedos de los pies ligeramente apuntando hacia fuera. Sujeta las asas a los lados de la máquina para mayor estabilidad. Activa el core y baja lentamente el cuerpo doblando las rodillas y las caderas, manteniendo la espalda recta. Continúa bajando hasta que los muslos queden paralelos al suelo o un poco por debajo. Haz una pausa por un momento en la posición baja, luego empuja con los talones para extender las piernas y volver a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0741-gf3ZjB9.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0741-gf3ZjB9.gif'),
('0742', 'sled forward angled calf raise', 'lower legs', 'sled machine', 'calves', 'hamstrings', '{"hamstrings","glutes"}', 'Ajusta la máquina de trineo a un peso cómodo y colócate en la máquina con la punta de los pies sobre la plataforma y los talones colgando. Coloca las manos en las asas o a los lados de la máquina para apoyarte. Activa las pantorrillas y eleva lentamente los talones lo más alto posible, empujando contra la resistencia del trineo. Haz una pausa breve en la parte alta del movimiento, luego baja lentamente los talones de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0742-XDOiFns.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0742-XDOiFns.gif'),
('0743', 'sled hack squat', 'upper legs', 'sled machine', 'glutes', 'quadriceps', '{"quadriceps","hamstrings","calves"}', 'Ajusta la máquina de trineo a una posición cómoda según tu altura. Ponte de pie con los pies separados a la altura de los hombros sobre la plataforma, con los dedos de los pies ligeramente apuntando hacia fuera. Sujétate de las asas o barras para mayor estabilidad. Baja el cuerpo doblando las rodillas y las caderas, manteniendo la espalda recta y el pecho elevado. Continúa bajando hasta que los muslos queden paralelos al suelo o un poco por debajo. Haz una pausa por un momento, luego empuja con los talones para subir el cuerpo de nuevo a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0743-Qa55kX1.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0743-Qa55kX1.gif'),
('2334', 'sled lying calf press', 'lower legs', 'sled machine', 'calves', 'hamstrings', '{"hamstrings","glutes"}', 'Ajusta la máquina de trineo a un peso adecuado. Siéntate en la máquina de trineo con la espalda contra el respaldo y los pies sobre la plataforma. Coloca la punta y la almohadilla de los pies en el borde de la plataforma, con los talones colgando. Empuja la plataforma alejándola de ti extendiendo los tobillos, manteniendo las rodillas ligeramente flexionadas. Continúa empujando hasta que las pantorrillas estén completamente contraídas. Mantén la contracción por un momento, luego baja lentamente la plataforma de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/2334-g376LuL.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/2334-g376LuL.gif'),
('0744', 'sled lying squat', 'upper legs', 'sled machine', 'glutes', 'quadriceps', '{"quadriceps","hamstrings","calves"}', 'Ajusta la máquina de trineo a un peso adecuado. Túmbate boca arriba en la máquina de trineo con los pies sobre la placa. Coloca los pies separados a la altura de los hombros y ligeramente angulados hacia fuera. Sujeta las asas de la máquina de trineo para mayor estabilidad. Activa los glúteos y los músculos del core. Empuja con los talones y extiende las piernas para levantar el trineo. Baja el trineo de nuevo doblando las rodillas y las caderas. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0744-9n2149Z.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0744-9n2149Z.gif'),
('1392', 'sled one leg calf press on leg press', 'lower legs', 'sled machine', 'calves', 'hamstrings', '{"hamstrings","glutes"}', 'Ajusta el asiento de la máquina de prensa de piernas de modo que las rodillas queden ligeramente flexionadas cuando los pies estén sobre el trineo. Siéntate en la máquina con la espalda contra el respaldo y los pies sobre el trineo, separados a la altura de los hombros. Coloca la punta y la almohadilla de los pies sobre el trineo, manteniendo los talones levantados. Empuja el trineo hacia delante extendiendo los tobillos, manteniendo las rodillas ligeramente flexionadas. Haz una pausa por un momento en la posición alta, luego baja lentamente el trineo flexionando los tobillos. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1392-u0pLNgz.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1392-u0pLNgz.gif'),
('1496', 'sledge hammer', 'waist', 'hammer', 'abs', 'forearms', '{"forearms","shoulders"}', 'Ponte de pie con los pies separados a la altura de los hombros y sujeta el mazo con ambas manos. Activa el core y mantén la espalda recta. Balancea el mazo hacia el suelo, usando la fuerza del core y de la parte superior del cuerpo. Mientras balanceas hacia abajo, gira las caderas y transfiere la fuerza al mazo. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1496-REXmfVC.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1496-REXmfVC.gif'),
('0746', 'smith back shrug', 'back', 'smith machine', 'traps', 'shoulders', '{"shoulders"}', 'Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas. Agarra la barra con un agarre pronado, con las manos un poco más separadas que el ancho de los hombros. Mantén los brazos rectos y deja que la barra cuelgue frente a los muslos. Levanta los hombros directamente hacia las orejas, contrayendo los trapecios en la parte alta. Mantén la posición por un momento, luego baja los hombros de nuevo a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0746-MzNnwx9.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0746-MzNnwx9.gif'),
('0747', 'smith behind neck press', 'shoulders', 'smith machine', 'delts', 'triceps', '{"triceps","upper back"}', 'Ajusta la altura del asiento de la máquina Smith de modo que la barra quede a la altura de los hombros. Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas. Sujeta la barra con agarre prono, un poco más separado que el ancho de los hombros. Levanta la barra del soporte y da un paso atrás, manteniendo una postura estable. Baja la barra hacia la parte de atrás del cuello, manteniendo los codos apuntando hacia delante. Empuja la barra hacia arriba, por encima de la cabeza, hasta que los brazos queden completamente extendidos. Haz una pausa por un momento en la posición alta, luego baja lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0747-Gpn4ADc.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0747-Gpn4ADc.gif'),
('0748', 'smith bench press', 'chest', 'smith machine', 'pectorals', 'triceps', '{"triceps","shoulders"}', 'Ajusta la altura de la barra de la máquina Smith a la altura del pecho. Túmbate en el banco con los pies firmemente apoyados en el suelo. Sujeta la barra con agarre prono, un poco más separado que el ancho de los hombros. Suelta la barra del soporte y bájala hacia el pecho, manteniendo los codos pegados al cuerpo. Haz una pausa por un momento cuando la barra toque el pecho. Empuja la barra de vuelta a la posición inicial, extendiendo los brazos por completo. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0748-trqKQv2.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0748-trqKQv2.gif'),
('0749', 'smith bent knee good morning', 'upper legs', 'smith machine', 'glutes', 'hamstrings', '{"hamstrings","lower back"}', 'Comienza de pie con los pies separados a la altura de los hombros, con los dedos de los pies apuntando hacia delante. Coloca la barra sobre la parte superior de la espalda, apoyándola en los trapecios. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta. Baja el torso hasta que quede paralelo al suelo, sintiendo un estiramiento en los isquiotibiales. Activa los glúteos y los isquiotibiales para levantar el torso de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0749-1bQkKZK.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0749-1bQkKZK.gif'),
('1359', 'smith bent over row', 'back', 'smith machine', 'upper back', 'biceps', '{"biceps","forearms"}', 'Configura la máquina Smith con la barra a la altura de la cadera. Ponte de pie frente a la barra con los pies separados a la altura de los hombros. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta. Sujeta la barra con un agarre prono, con las manos un poco más separadas que el ancho de los hombros. Tira de la barra hacia la parte baja del pecho, juntando las escápulas. Haz una pausa por un momento en la posición alta, luego baja lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1359-ZX9UZmj.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1359-ZX9UZmj.gif'),
('0750', 'smith chair squat', 'upper legs', 'smith machine', 'quads', 'glutes', '{"glutes","hamstrings","calves"}', 'Ajusta la altura de la barra de la máquina Smith a una posición cómoda. Ponte de pie con los pies separados a la altura de los hombros, con los dedos de los pies ligeramente hacia afuera. Coloca la barra sobre la parte superior de la espalda, apoyándola en los trapecios. Activa el core y mantén el pecho elevado mientras bajas lentamente el cuerpo doblando las rodillas y las caderas. Continúa bajando hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente. Haz una pausa breve y luego empuja con los talones para volver a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0750-Gu2rNJd.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0750-Gu2rNJd.gif'),
('0751', 'smith close-grip bench press', 'upper arms', 'smith machine', 'triceps', 'chest', '{"chest","shoulders"}', 'Ajusta la altura del asiento y colócate en el banco con los pies planos sobre el suelo. Agarra la barra con un agarre cerrado, un poco más estrecho que el ancho de los hombros. Baja la barra hacia el pecho, manteniendo los codos pegados cerca del cuerpo. Haz una pausa breve en la parte baja y luego empuja la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0751-WcHl7ru.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0751-WcHl7ru.gif'),
('0752', 'smith deadlift', 'upper legs', 'smith machine', 'glutes', 'hamstrings', '{"hamstrings","quadriceps","lower back"}', 'Configura la máquina Smith con la barra a la altura de la cadera. Ponte de pie con los pies separados a la altura de los hombros, los dedos de los pies ligeramente hacia afuera. Dobla las caderas y las rodillas, manteniendo la espalda recta y el pecho elevado, y sujeta la barra con un agarre prono un poco más ancho que los hombros. Activa el core y levanta la barra extendiendo las caderas y las rodillas, manteniendo la barra cerca del cuerpo. Ponte de pie erguido, extendiendo por completo las caderas y las rodillas. Baja la barra de nuevo doblando las caderas y las rodillas, manteniendo el control y la espalda recta. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0752-UfePqpx.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0752-UfePqpx.gif'),
('0753', 'smith decline bench press', 'chest', 'smith machine', 'pectorals', 'triceps', '{"triceps","shoulders"}', 'Ajusta el banco declinado al ángulo deseado. Túmbate en el banco con los pies asegurados bajo las almohadillas para los pies. Agarra la barra con un agarre pronado un poco más ancho que la separación de los hombros. Saca la barra del soporte y bájala lentamente hacia el pecho, manteniendo los codos pegados al cuerpo. Haz una pausa breve en la parte baja y luego empuja la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0753-ETZfAbZ.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0753-ETZfAbZ.gif'),
('0754', 'smith decline reverse-grip press', 'chest', 'smith machine', 'pectorals', 'triceps', '{"triceps","shoulders"}', 'Ajusta la máquina Smith a una posición declinada. Túmbate en el banco con los pies asegurados bajo las almohadillas para los pies. Agarra la barra con un agarre invertido, manos un poco más separadas que el ancho de los hombros. Suelta la barra y bájala hacia el pecho, manteniendo los codos pegados al cuerpo. Haz una pausa breve en la parte baja y luego empuja la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0754-MY9P1WA.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0754-MY9P1WA.gif'),
('1433', 'smith front squat (clean grip)', 'upper legs', 'smith machine', 'glutes', 'quadriceps', '{"quadriceps","hamstrings","calves","core"}', 'Configura la máquina Smith con la barra a la altura de los hombros. Ponte de pie frente a la barra con los pies separados a la altura de los hombros. Agarra la barra con un agarre pronado un poco más ancho que la separación de los hombros. Da un paso atrás y coloca la barra sobre los hombros delanteros, apoyándola en la clavícula y los deltoides. Mantén el pecho elevado, la espalda recta y el core activado. Baja el cuerpo doblando las rodillas y las caderas, como si te sentaras en una silla. Continúa bajando hasta que los muslos queden paralelos al suelo o un poco por debajo. Haz una pausa breve y luego empuja con los talones para volver a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1433-lFhb2Rw.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1433-lFhb2Rw.gif'),
('3281', 'smith full squat', 'upper legs', 'smith machine', 'glutes', 'quadriceps', '{"quadriceps","hamstrings","calves"}', 'Configura la máquina Smith con la barra a la altura de los hombros. Ponte de pie con los pies separados a la altura de los hombros, con los dedos de los pies ligeramente hacia afuera. Colócate debajo de la barra y posiciónala sobre la parte alta de la espalda, apoyándola en los trapecios. Sujeta la barra con las manos un poco más separadas que el ancho de los hombros. Suelta la barra del soporte y da un paso atrás, manteniendo una postura estable. Manteniendo el pecho elevado y el core activado, inicia la sentadilla empujando las caderas hacia atrás y doblando las rodillas. Baja el cuerpo hasta que los muslos queden paralelos al suelo, o tan abajo como tu flexibilidad lo permita. Haz una pausa por un momento en la posición baja, luego empuja con los talones para volver a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/3281-NNoHCEA.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3281-NNoHCEA.gif'),
('0755', 'smith hack squat', 'upper legs', 'smith machine', 'glutes', 'quadriceps', '{"quadriceps","hamstrings","calves"}', 'Ajusta la barra de la máquina Smith a una altura adecuada para tu cuerpo. Ponte de pie con los pies separados a la altura de los hombros, con los dedos de los pies ligeramente hacia afuera. Colócate debajo de la barra, apoyándola en la parte alta de los trapecios y los hombros. Agarra la barra con un agarre pronado un poco más ancho que la separación de los hombros. Activa el core y mantén el pecho elevado mientras sueltas la barra del soporte. Da un paso atrás y coloca los pies un poco más separados que el ancho de los hombros. Dobla las rodillas y baja el cuerpo, manteniendo el pecho elevado y la espalda recta. Continúa descendiendo hasta que los muslos queden paralelos al suelo o un poco por debajo. Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0755-ZuPXtCK.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0755-ZuPXtCK.gif'),
('0756', 'smith hip raise', 'waist', 'smith machine', 'abs', 'glutes', '{"glutes","hamstrings"}', 'Colócate en la máquina Smith con la espalda contra la almohadilla y los pies separados a la altura de los hombros. Coloca las manos en la barra, un poco más separadas que el ancho de los hombros. Activa el core y los glúteos, luego empuja con los talones para levantar las caderas del suelo. Continúa levantando hasta que el cuerpo forme una línea recta desde las rodillas hasta los hombros. Mantén la posición alta por un momento, luego baja lentamente las caderas de nuevo a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0756-CqhoytW.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0756-CqhoytW.gif'),
('0757', 'smith incline bench press', 'chest', 'smith machine', 'pectorals', 'shoulders', '{"shoulders","triceps"}', 'Ajusta el banco a una inclinación de 30-45 grados. Siéntate en el banco con la espalda plana contra la almohadilla y los pies firmemente apoyados en el suelo. Agarra la barra con un agarre pronado un poco más ancho que la separación de los hombros. Suelta la barra y bájala lentamente hacia la parte alta del pecho, manteniendo los codos ligeramente pegados al cuerpo. Haz una pausa por un momento en la posición baja, luego empuja la barra de vuelta a la posición inicial, extendiendo los brazos por completo. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0757-5v7KYld.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0757-5v7KYld.gif'),
('0758', 'smith incline reverse-grip press', 'chest', 'smith machine', 'pectorals', 'triceps', '{"triceps","shoulders"}', 'Ajusta el asiento de la máquina Smith a un ángulo de inclinación cómodo. Siéntate en la máquina con la espalda contra la almohadilla y los pies planos sobre el suelo. Sujeta la barra con un agarre prono un poco más ancho que el ancho de los hombros. Suelta la barra y bájala lentamente hacia el pecho, manteniendo los codos pegados al cuerpo. Haz una pausa por un momento cuando la barra esté justo por encima del pecho. Empuja la barra de vuelta a la posición inicial, extendiendo los brazos por completo. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0758-78VqWQK.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0758-78VqWQK.gif'),
('0759', 'smith incline shoulder raises', 'chest', 'smith machine', 'serratus anterior', 'deltoids', '{"deltoids","trapezius"}', 'Ajusta la máquina Smith a una posición inclinada. Ponte de pie frente a la máquina con los pies separados a la altura de los hombros. Sujeta la barra con agarre prono, un poco más separado que el ancho de los hombros. Mantén la espalda recta y el core activado. Eleva la barra hacia el techo, guiando el movimiento con los codos. Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0759-ayAHcEm.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0759-ayAHcEm.gif'),
('0760', 'smith leg press', 'upper legs', 'smith machine', 'glutes', 'quadriceps', '{"quadriceps","hamstrings","calves"}', 'Ajusta el asiento y la placa para los pies de la máquina Smith a una posición cómoda. Siéntate en la máquina con la espalda apoyada en el respaldo y los pies separados a la altura de los hombros sobre la placa para los pies. Sujeta las asas o los lados de la máquina para mayor estabilidad. Empuja la placa alejándola de ti extendiendo las piernas, manteniendo la espalda contra el respaldo. Haz una pausa por un momento en la posición completamente extendida. Dobla lentamente las rodillas y baja la placa de vuelta hacia ti, regresando a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0760-7zdxRTl.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0760-7zdxRTl.gif'),
('1434', 'smith low bar squat', 'upper legs', 'smith machine', 'glutes', 'quadriceps', '{"quadriceps","hamstrings","calves"}', 'Configura la máquina Smith con la barra a una altura que te permita apoyarla cómodamente en la parte alta de la espalda. Ponte de pie con los pies separados a la altura de los hombros, con los dedos de los pies ligeramente hacia afuera. Colócate debajo de la barra y posiciónala sobre la parte alta de la espalda, apoyándola en los trapecios. Sujeta la barra con las manos un poco más separadas que el ancho de los hombros. Suelta la barra del soporte estirando las piernas y dando un paso atrás para alejarte del soporte. Respira profundamente y tensa el core. Inicia la sentadilla empujando las caderas hacia atrás y doblando las rodillas. Baja el cuerpo hasta que los muslos queden paralelos al suelo o un poco por debajo. Mantén el pecho hacia arriba y la espalda recta durante todo el movimiento. Empuja con los talones para volver a ponerte de pie, extendiendo las caderas y las rodillas. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1434-RGLscZM.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1434-RGLscZM.gif'),
('1683', 'smith machine bicep curl', 'upper arms', 'smith machine', 'biceps', 'forearms', '{"forearms"}', 'Ajusta la altura de la barra de la máquina Smith a la altura de la cintura. Ponte de pie frente a la máquina Smith con los pies separados a la altura de los hombros. Sujeta la barra con un agarre supino, con las manos un poco más separadas que el ancho de los hombros. Mantén los codos cerca de los costados y los brazos superiores quietos. Exhala y flexiona la barra hacia los hombros, contrayendo los bíceps. Haz una pausa breve en la parte más alta del movimiento, contrayendo los bíceps. Inhala y baja lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1683-zILLZ98.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1683-zILLZ98.gif'),
('1625', 'smith machine decline close grip bench press', 'upper arms', 'smith machine', 'triceps', 'chest', '{"chest","shoulders"}', 'Ajusta el banco de la máquina Smith a una posición declinada. Túmbate en el banco con los pies firmemente apoyados en el suelo. Agarra la barra con un agarre cerrado, un poco más estrecho que el ancho de los hombros. Saca la barra del soporte y bájala lentamente hacia el pecho, manteniendo los codos cerca del cuerpo. Haz una pausa breve cuando la barra esté justo encima del pecho. Empuja la barra de vuelta a la posición inicial, extendiendo completamente los brazos. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1625-yB9SvIF.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1625-yB9SvIF.gif'),
('1752', 'smith machine incline tricep extension', 'upper arms', 'smith machine', 'triceps', 'shoulders', '{"shoulders"}', 'Ajusta el asiento de la máquina Smith de modo que la barra quede a la altura de los hombros. Siéntate en el banco con la espalda apoyada en el respaldo y los pies planos sobre el suelo. Sujeta la barra con agarre prono, un poco más separado que el ancho de los hombros. Extiende los brazos por completo, levantando la barra del soporte y sosteniéndola directamente sobre el pecho. Baja la barra lentamente hacia la frente, manteniendo los codos cerca de la cabeza. Haz una pausa por un momento en la posición baja, luego empuja la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1752-o8aOcrz.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1752-o8aOcrz.gif'),
('1626', 'smith machine reverse decline close grip bench press', 'chest', 'smith machine', 'pectorals', 'triceps', '{"triceps","shoulders"}', 'Ajusta la máquina Smith a una posición declinada. Túmbate en el banco con los pies asegurados bajo las almohadillas para los pies. Agarra la barra con un agarre cerrado, un poco más estrecho que el ancho de los hombros. Saca la barra del soporte y bájala lentamente hacia el pecho, manteniendo los codos pegados al cuerpo. Haz una pausa breve en la parte baja y luego empuja la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1626-QyO6Uma.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1626-QyO6Uma.gif'),
('0761', 'smith narrow row', 'back', 'smith machine', 'upper back', 'biceps', '{"biceps","rear deltoids"}', 'Ajusta la altura del asiento y colócate en la máquina con los pies planos sobre el suelo. Sujeta las asas con un agarre prono, un poco más estrecho que el ancho de los hombros. Mantén la espalda recta y el pecho elevado mientras tiras de las asas hacia tu cuerpo, juntando las escápulas. Haz una pausa por un momento en el punto máximo del movimiento, luego suelta lentamente las agarraderas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0761-JGKowMS.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0761-JGKowMS.gif'),
('1360', 'smith one arm row', 'back', 'smith machine', 'upper back', 'biceps', '{"biceps","forearms"}', 'Ajusta la altura de la barra de la máquina Smith a la altura de la cintura. Ponte de pie frente a la máquina Smith con los pies separados a la altura de los hombros. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta. Sujeta la barra con una mano usando un agarre prono, con la palma hacia abajo. Mantén el codo cerca del cuerpo y tira de la barra hacia la cintura, juntando las escápulas. Haz una pausa por un momento en la parte alta del movimiento, luego baja lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia al otro brazo.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1360-Q4DSJPC.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1360-Q4DSJPC.gif'),
('1393', 'smith one leg floor calf raise', 'lower legs', 'smith machine', 'calves', 'hamstrings', '{"hamstrings","glutes"}', 'Colócate en el suelo debajo de la barra de la máquina Smith, mirando en dirección contraria a la máquina. Coloca la punta de los pies sobre una superficie elevada, como un disco de peso o un bloque. Coloca la barra de la máquina Smith sobre la parte baja de las piernas, justo por encima de los tobillos. Sujeta la barra con las manos para mayor estabilidad. Levanta los talones del suelo extendiendo los tobillos, elevando el cuerpo hacia arriba. Haz una pausa en la parte alta del movimiento, luego baja lentamente los talones de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1393-9GXrTE6.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1393-9GXrTE6.gif'),
('0762', 'smith rear delt row', 'shoulders', 'smith machine', 'delts', 'trapezius', '{"trapezius","rhomboids","biceps"}', 'Ajusta la altura del asiento y colócate en la máquina con el pecho contra la almohadilla y los pies planos en el suelo. Agarra las agarraderas con un agarre prono, un poco más separadas que el ancho de los hombros. Mantén la espalda recta y el core activado mientras tiras de las asas hacia el pecho, juntando las escápulas. Haz una pausa por un momento en la parte alta del movimiento, luego suelta lentamente las asas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0762-nFUwqG6.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0762-nFUwqG6.gif'),
('0763', 'smith reverse calf raises', 'lower legs', 'smith machine', 'calves', 'hamstrings', '{"hamstrings"}', 'Ajusta la barra de la máquina Smith a una altura justo debajo de los hombros. Ponte de pie frente a la barra con los pies separados a la altura de la cadera y los dedos de los pies apuntando hacia delante. Coloca la punta de los pies en el borde de un escalón o plataforma, con los talones colgando. Sujétate de la barra para apoyarte, manteniendo la espalda recta y el core activado. Levanta los talones lo más alto posible, elevando el peso de tu cuerpo sobre las puntas de los pies. Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0763-ywaNfuh.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0763-ywaNfuh.gif'),
('1394', 'smith reverse calf raises', 'lower legs', 'smith machine', 'calves', 'hamstrings', '{"hamstrings"}', 'Ajusta la barra de la máquina Smith a una altura justo debajo de los hombros. Ponte de pie frente a la barra con los pies separados a la altura de la cadera y los dedos de los pies apuntando hacia delante. Coloca la punta de los pies en el borde de un escalón o plataforma, con los talones colgando. Sujétate de la barra para apoyarte. Levanta los talones lo más alto posible, elevando el cuerpo sobre la punta de los pies. Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1394-Lsqrgh4.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1394-Lsqrgh4.gif'),
('1361', 'smith reverse grip bent over row', 'back', 'smith machine', 'upper back', 'biceps', '{"biceps","forearms"}', 'Configura la máquina Smith con la barra a la altura de la cadera. Ponte de pie frente a la barra con los pies separados a la altura de los hombros. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta. Sujeta la barra con agarre supino, manos separadas a la altura de los hombros. Tira de la barra hacia la parte baja del pecho, juntando las escápulas. Haz una pausa por un momento en la posición alta, luego baja lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1361-aaxA3cm.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1361-aaxA3cm.gif');
